// Pedersen / ElGamal parity test. Verifies public/pedersen.js produces
// byte-identical output to prover/pedersen.go on a fixed set of inputs.
//
// Vectors regenerated by:
//   BITWRAP_EMIT_VECTORS=1 go test ./prover/ -run TestEmitParityVectors
//
// Run: node public/pedersen_parity_test.mjs

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import {
    Fr,
    SUBGROUP_ORDER,
    G,
    encodePointHex,
    decodePointHex,
    encrypt,
    aggregate,
    decrypt,
    pointEq,
    isInPrimeSubgroup,
    setPedersenH,
    getPedersenH,
    scalarMulBase,
} from './pedersen.js';

const here = dirname(fileURLToPath(import.meta.url));
const vectors = JSON.parse(
    readFileSync(join(here, 'pedersen_vectors.json'), 'utf8'),
);

let failures = 0;
function assert(cond, msg) {
    if (!cond) {
        console.error('FAIL:', msg);
        failures++;
    } else {
        console.log('OK:  ', msg);
    }
}
function assertEq(got, want, msg) {
    assert(got === want, `${msg}\n     got:  ${got}\n     want: ${want}`);
}

// 1. Curve constants pinned.
assertEq(Fr.toString(), vectors.scalarModulus, 'Fr matches');
assertEq(SUBGROUP_ORDER.toString(), vectors.subgroupOrder, 'subgroup order matches');

// 2. G round-trips through encode/decode.
assertEq(encodePointHex(G), vectors.G, 'G encoding matches');
const gDecoded = decodePointHex(vectors.G);
assert(pointEq(gDecoded, G), 'G decodes back to canonical generator');

// 3. H loaded as a constant; byte-sequence agreement is the parity claim.
setPedersenH(vectors.H);
assertEq(encodePointHex(getPedersenH()), vectors.H, 'H round-trips');
assert(isInPrimeSubgroup(getPedersenH()), 'H is in prime-order subgroup');

// 4. pk = G·sk parity.
const sk = BigInt(vectors.sk);
const pk = decodePointHex(vectors.pk);
const pkComputed = scalarMulBase(sk);
assertEq(encodePointHex(pkComputed), vectors.pk, 'pk = G·sk matches');

// 5. Each Encrypt case produces identical ciphertexts.
for (const [i, c] of vectors.encrypts.entries()) {
    const ct = encrypt(BigInt(c.v), BigInt(c.r), pk);
    assertEq(encodePointHex(ct.A), c.ct.A, `encrypt[${i}] A matches (v=${c.v}, r=${c.r})`);
    assertEq(encodePointHex(ct.B), c.ct.B, `encrypt[${i}] B matches`);
}

// 6. Aggregate of the fixture inputs matches Go's sum byte-for-byte.
const inputs = vectors.aggregate.inputs.map((c) => ({
    A: decodePointHex(c.A),
    B: decodePointHex(c.B),
}));
const sum = aggregate(inputs);
assertEq(encodePointHex(sum.A), vectors.aggregate.sum.A, 'aggregate A matches');
assertEq(encodePointHex(sum.B), vectors.aggregate.sum.B, 'aggregate B matches');

// 7. Decrypt of the aggregate recovers the same tally Go did.
const tally = decrypt(sum, sk, vectors.decrypt.maxTally);
assertEq(tally, vectors.decrypt.tally, 'decrypt(aggregate) matches');

if (failures > 0) {
    console.error(`\n${failures} parity check(s) FAILED`);
    process.exit(1);
}
console.log('\nAll Pedersen / ElGamal parity checks passed.');
